@startuml

class Song {
  + title : string
  + year : int
  + length : int
  + genre : string
}

class Artist {
  + name : string
  + dateOfBirth : date
  + websiteURL : string
}

class User {
  + userID : int
  + name : string
  + address : string
}

class BusinessUser extends User {
  + VATNumber : string
}

class RegularUser extends User {}

class Single extends Song {}

class Hit extends Song {}

class Album {
  + trackNumber : int
}

Artist "1" -- "*" Song : belongs to
BusinessUser "1" -- "*" Song : uploads
RegularUser "1" -- "*" Single : buys
RegularUser "1" -- "*" Album : composes
Album "1" *-- "1..*" Hit : consists of

@enduml

